class.description:
A [MultiplayerPeer] that sends Godot's high-level multiplayer traffic (RPCs, [MultiplayerSpawner], [MultiplayerSynchronizer]) over Steam Networking Sockets. Players connect to each other by Steam ID, through the Steam Datagram Relay network, so no port forwarding or public IP address is needed and players' IP addresses stay hidden.
One player hosts with [method create_host] and becomes peer [code]1[/code]; the others connect with [method create_client] using the host's Steam ID, typically found through a Steam lobby (see [method Steam.create_lobby]). Clients only connect to the host, which relays messages between clients ([member SceneMultiplayer.server_relay]).
Steam must be initialized with [method Steam.initialize] first.
[codeblock]
# Host.
func _on_lobby_created(result: int, lobby_id: int):
	var peer := SteamMultiplayerPeer.new()
	peer.create_host()
	multiplayer.multiplayer_peer = peer


# Client, after Steam.join_lobby().
func _on_lobby_joined(lobby_id: int, response: int):
	var host_id := Steam.get_lobby_owner(lobby_id)
	if response != Steam.LOBBY_ENTER_SUCCESS or host_id == Steam.get_local_steam_id():
		return
	var peer := SteamMultiplayerPeer.new()
	peer.create_client(host_id)
	multiplayer.multiplayer_peer = peer
[/codeblock]
[b]Note:[/b] Steam has no unordered reliable or ordered unreliable delivery. [constant MultiplayerPeer.TRANSFER_MODE_RELIABLE] is always ordered, and [constant MultiplayerPeer.TRANSFER_MODE_UNRELIABLE_ORDERED] drops packets that arrive after a newer one on the same channel. Channels only label packets; they don't create separate ordered streams.
[b]Note:[/b] Two Steam accounts are needed to test a connection; a player can't connect to themselves.
